import numpy as np

def hedge(greeks, target):
    return np.linalg.solve(np.array(greeks, dtype=float), np.array(target, dtype=float))

def hedge_or_none(greeks, target):
    # return hedge(greeks, target), or None when the matrix is singular
    try:
        return hedge(greeks, target)
    except np.linalg.LinAlgError:
        return None

